#!/usr/bin/env python3
"""Author the 64-cue AI-bubble episode from the supplied narration blueprint."""
import json, re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
ep = json.loads((ROOT / 'episodes/ai-bubble.json').read_text(encoding='utf-8'))
V = ROOT / 'reference/analysis/scene_stills'
refs = {int(p.name.split('_')[1]): str(p.relative_to(ROOT)) for p in V.glob('*.jpg')}
PAPER='#E9E4D2'; INK='#12141C'; BLUE='#2F3BFF'; RED='#FF3D17'; SLATE='#6F7388'; GREEN='#216E50'

def O(typ,x,y=455,**kw): return dict(type=typ,x=x,y=y,instant=True,**kw)
def L(text,x=480,y=145,size=34,**kw): return O('label',x,y,text=text,size=size,maxWidth=830,**kw)
def A(x=250,y=455,action='explain',**kw): return O('person',x,y,h=kw.pop('h',170),action=action,**kw)
def G(x=250,y=455,action='explain',**kw): return A(x,y,action,role='guide',castId='guide',color=RED,legColor=INK,**kw)
def K(obj,field,a,b,d=1.4,delay=0): obj['keyframes']=[{'at':delay,field:a},{'at':delay+d,field:b}]; return obj
def VEC(x,y,shapes,**kw): return O('vector',x,y,shapes=shapes,**kw)
def rect(x,y,w,h,fill,**kw): return dict(kind='rect',x=x,y=y,w=w,h=h,fill=fill,**kw)
def line(x,y,x2,y2,stroke=INK,width=3,**kw): return dict(kind='line',x=x,y=y,x2=x2,y2=y2,stroke=stroke,width=width,**kw)
def poly(points,fill,**kw): return dict(kind='polygon',points=points,fill=fill,**kw)
def ell(x,y,rx,ry,fill,**kw): return dict(kind='ellipse',x=x,y=y,rx=rx,ry=ry,fill=fill,**kw)
def txt(text,x,y,size=24,fill=INK,**kw): return dict(kind='text',text=text,x=x,y=y,size=size,fill=fill,**kw)
def street(): return [O('building',110,390,h=180,label='ঢাকা'),O('tea_stall',790,445),O('palm',625,385),O('rickshaw',420,445,scale=.52,motion={'kind':'walk','speed':9})]
def desk(x=240,night=False,guide=True): return [G(x,455,'typing',pose='sit',h=150) if guide else A(x,455,'typing',pose='sit',h=150),O('desk',x+72,455,color=SLATE if night else INK,ai=True)]
def crowd(n,x=180,y=455,step=55,**kw): return [A(x+i*step,y,kw.pop('action','listen') if i==0 else 'listen',h=kw.pop('h',125),variant=i%6,phase=i*.63,**kw) for i in range(n)]
def tower(label='NVIDIA',x=620,h=245,color=SLATE): return [O('bar',x,455,w=150,h=h,color=color,text=label)]
def card(text,x,y=355,w=260,h=120,**kw): return O('card',x,y,w=w,h=h,text=text,size=kw.pop('size',24),**kw)
def grid(n,x,y=425,cols=10,active=None,color=BLUE): return O('grid',x,y,count=n,cols=cols,active=n if active is None else active,color=color)
def link(a,b,**kw): return {'from':a,'to':b,**kw}

def S(i,ref,backdrop,setting,action,change,objects,alternative,hold=False,links=None,camera=None):
    b=ep['beats'][i]
    for j,o in enumerate(objects): o['id']=o.get('id',f'b{i+1:03}-o{j:02}')
    b.update(scene='compose',cueIndex=i,scriptLine=ep['cues'][i]['text'],heading='',visualIntent=f'{action} {change}',
             styleRefs=[refs[ref]],shot={'backdrop':backdrop,'objects':objects,'links':links or []})
    if camera: b['shot']['camera']=camera
    people=[o for o in objects if o['type']=='person']
    b['semanticAnalysis']={'actors':[o.get('castId',o.get('role','participant')) for o in people],
      'action':action,'setting':setting,'facts':[b['scriptLine']],
      'relationship':change,'tone':'Investigative, restrained and explanatory.',
      'negation':'Preserve every denial, comparison and qualification in the supplied narration.',
      'uncertainty':'Claims and approximate figures remain attributed to the supplied script; they are not independently fact-checked.'}
    b['designDecision']={'alternatives':[action,alternative],'mechanism':setting,
      'composition':action,'visibleChange':change,'actionPeak':change,
      'cameraPurpose':'A locked or discrete camera change preserves reading order and the central relationship.',
      'transition':'Hard editorial cut unless the shot declares a motivated reveal.',
      'why':'The selected mechanism turns the line’s causal or numerical relationship into a visible consequence.'}
    b['referenceUse']=['Borrow the selected reference’s flat material, slender figures, grounded scale, restrained palette, readable evidence staging and editorial pacing.']
    b['continuity']={'cast':'The vermilion guide keeps the same clothing, proportions and role.','place':setting,'props':'Recurring phones, servers, ledgers and blue AI marks retain their visual identity.'}
    b['animationPlan']={'primaryAction':action,'motivation':'Make the narration’s central relationship visible.',
      'anticipation':'Gaze and acting hand orient before the main reveal.','contact':'Hands meet held or operated props through rig sockets where applicable.',
      'weightShift':'The acting figure shifts toward the target without foot sliding.','actionPeak':change,
      'followThrough':'The action settles and holds long enough to read.','secondaryMotion':'Only supporting screens, paper, vehicles or data marks move.',
      'gaze':'The principal figure looks toward the consequence or evidence.','cameraMotivation':'Reveal scale or a causal connection; otherwise remain locked.',
      'intentionalHold':hold,'holdReason':'Evidence or closing text needs quiet reading time.' if hold else ''}
    copy=[]; nums=[]
    for o in objects:
        for key in ('text','label','line1','line2','number','value'):
            if o.get(key) not in (None,''):
                value=str(o[key]); copy.append({'text':value,'basis':'script' if value in b['scriptLine'] else 'editorial','explanation':'Exact script wording or concise editorial label used to explain this cue.'})
                nums += re.findall(r'[0-9০-৯][0-9০-৯, ]*',value)
    b['copyLedger']=copy
    b['factBasis']=[{'value':n,'basis':'script' if n in b['scriptLine'] else 'editorial','explanation':'Quantity is stated by the supplied script or used only as an editorial chapter/layout marker.'} for n in dict.fromkeys(nums)]
    b['review']={'start':'Pending rendered inspection.','middle':'Pending rendered inspection.','end':'Pending rendered inspection.','issues':[],'fixes':[],'approved':False}

